@startuml

class Sober {
}

class Car {
  + vehicleNumber : string
}

class Owner {
  + name : string
}

class Accident {
  + date : date
  + location : string
  + damageAmount : double
}

class RideHail {
  + pickUpTime : datetime
  + dropOffTime : datetime
  + pickUpLocation : string
  + dropOffLocation : string
  + duration : string
  + distance : double
  + passengerCount : int
  + fee : double
  + requestType : string
}

class RideShare {
  + pickUpTime : datetime
  + dropOffTime : datetime
  + pickUpLocation : string
  + dropOffLocation : string
  + duration : string
  + distance : double
  + negotiatedFee : double
}

class Customer {
  + name : string
}

class RideHailCustomer {
  + name : string
}

class RideShareCustomer {
  + name : string
}

Car "0..*" -- "0..1" Owner : owned by
Car "1" -- "0..*" Accident : involved in
Car "1" -- "0..*" RideHail : used for
Car "1" -- "0..*" RideShare : used for
RideHail "0..*" -- "1" RideHailCustomer : lead customer
RideShare "0..*" -- "1..*" RideShareCustomer : passenger
RideShare "0..*" -- "1" Car : used for

@enduml

